/**
 * Did the fill land? — the one module that judges a field's reading against what it should hold (A2, 2026-11-01).
 * Until then that was judged in four modules by three rules of the earlier text, and D28 and D29 were both bugs of
 * the typing and the verdict judging the same reading differently. Three questions, one answer each:
 * - `landingOf`: did this reading land — exactly, reformatted, or only as the field's placeholder — or is it a masked
 *   reading that proves the field was wrongly said plain?
 * - `tailOf` (and `droppedTail`): is it a strict prefix of what the field should hold — the tail a field dropped?
 * - `differenceOf`: what can be said of a reading that missed, without content?
 * interact/fill-type.ts asks the first two as it types, polls and retypes; it asks the third once, for a typing that
 * missed, and fill.ts throws what comes back. fill.ts asks one more (`needsHeldCount`): whether the field can hold
 * bullets the masked rule must count from — its post-focus re-read's gate. Pure: no device, no wait, no sentence. Its
 * imports are the facts (fill-facts.ts), the character rules of a reformatting field (fill-reformat.ts), the mask
 * characters and the input role.
 */

import { INPUT_ROLE, type UiNode } from '../adapters/types.js';
import { hasBullet, isMaskedValue } from '../ui-tree/masked-value.js';
import { heldText, type Difference, type Reformat } from './fill-facts.js';
import { prefixOf, reformatOf, skeleton } from './fill-reformat.js';

/** What the field should hold after the typing, and what the reading is judged against. */
export interface Expectation {
  /** The value typed; non-empty (an empty fill types nothing and reads nothing back). */
  value: string;
  /** The field was cleared first: it must EQUAL the value. Without, it must show the value after its earlier text. */
  clear: boolean;
  /** What the field showed when typing began (null: nothing) — the text the typing appends to. */
  before: string | null;
  /** The field's named placeholder (UiNode.placeholder): shown while empty, never content (fill-facts.ts#heldText). */
  placeholder: string | undefined;
  /** The matched node is an input (INPUT_ROLE); otherwise it proves it took the text only by changing to show it. */
  isInput: boolean;
  /** The matched node's value when it was resolved, before the focus tap — what a non-input shows of itself. */
  resolvedValue: string | null;
  /**
   * The bullets a masked field held after focus — a masked reading must show these plus the typed length. `'unread'`:
   * fill.ts skipped the post-focus re-read (`needsHeldCount`; docs/adr/0028-a-fill-re-reads-after-focus-only-where-
   * focus-can-change-the-count.md), the field being said plain, so what it held is unknown and only the typed length
   * passes a masked reading (`landingOf`'s `said-plain`).
   */
  held: number | 'unread';
}

/** What the text rules ask of an Expectation: the value, and the earlier text it is typed after. */
type TextExpectation = Pick<Expectation, 'value' | 'clear' | 'before' | 'placeholder'>;

/**
 * A reading that landed:
 * - `landed`: it shows the value — exactly, or `reformatted` (the field added separators of its own: `reformatOf`);
 * - `placeholder`: it is exactly the field's named placeholder, which is the value too — typed, or an empty field
 *   with the typing dropped; the tree cannot tell (review of the read-back, probe B). Not verified;
 * - `said-plain`: the held count is `'unread'` and the reading is masked, longer than typed — the field its source said
 *   is plain shows bullets after all, and no length of it proves anything but the typed one (two dropped keys under
 *   five autofilled bullets would pass `held + typed` with a `held` of 0). Final: the poll stops on it, as on a landed
 *   reading, and the fill fails `masked-said-plain` (`differenceOf`). A SHORTER masked reading has not landed and the
 *   poll goes on — its keys may still arrive; the timing of both is as it was when fill.ts overrode a landed reading.
 */
export type Landing = { kind: 'landed'; reformatted?: Reformat } | { kind: 'placeholder' } | { kind: 'said-plain' };

/**
 * Whether a reading landed, and how; undefined when it did not. The rules:
 * - a non-input proves it took the text only by CHANGING to show it (`tookText`);
 * - a field that reformats as it is typed (D18) lands when it shows what it should hold — its earlier text, unless
 *   cleared, then the value — every typed character in order, separators of its own added (`landedReformat`);
 * - else the reading must show the value exactly (`showsExactly`): with clear the whole reading, without it inside what
 *   the field holds; a masked reading by length.
 * A landed reading is `said-plain` when it shows bullets said plain (`bulletsSaidPlain`) and is longer than typed (a
 * shorter one has not landed), else `placeholder` when it is exactly the named placeholder. Pure.
 */
export function landingOf(observed: string, e: Expectation): Landing | undefined {
  if (!tookText(observed, e)) return undefined;
  const reformatted = landedReformat(observed, e);
  if (reformatted === undefined && !showsExactly(observed, e)) return undefined;
  if (bulletsSaidPlain(observed, e) && observed.length !== e.value.length) return { kind: 'said-plain' };
  if (e.placeholder !== undefined && observed === e.placeholder) return { kind: 'placeholder' };
  return { kind: 'landed', ...(reformatted !== undefined && { reformatted }) };
}

/**
 * A non-input proves it took the text only by CHANGING to show it: a WDA StaticText exposes its label as its value,
 * and "Meno".includes("e") is no fill; a label that changes on focus (`Name` → `Name*`) is no fill either, and the
 * clear's wipe and retype would delete ITS length into the focused field (review 2026-10-08, rounds 1 and 2). An
 * input-like node of another role (an iOS search field reads `other`) shows the typed text, so it still gets the
 * retry. Masked values cannot show it: for them the change alone is the proof, as their length is for inputs. A
 * reformatted reading (the value split by separators) never contains the value, so a non-input never lands one.
 */
export const tookText = (observed: string, e: Pick<Expectation, 'value' | 'isInput' | 'resolvedValue'>): boolean =>
  e.isInput || (observed !== e.resolvedValue && (isMaskedValue(observed) || observed.includes(e.value)));

/**
 * The reading shows the value as typed.
 *
 * A masked (secure) field shows one bullet per character to uiautomator and WDA alike, so its content can never EQUAL
 * the value — measured 2026-09-17 (finportal login): `typed 16 characters but the field shows 16` on both platforms,
 * for a fill that had landed. Its LENGTH still says whether every keystroke arrived, which is the check that matters on
 * a loaded emulator (dropped characters there surfaced as a backend `invalid_grant`), so a bullets-only reading is
 * compared by count, never by content. The rule detects the SHORT direction only — dropped keystrokes; without `clear`
 * the field must show at least what it held after focus plus what was typed. It cannot tell a correct append from
 * typing onto an autofilled password (both read `held + typed`); that case is fill.ts's `maskedAppend`, not a failure.
 * A held count `'unread'` counts as none (`heldCount`); `landingOf` fails any length but the typed one there.
 *
 * A placeholder is not content: on an empty field showing `Search`, nothing typed must not pass for a typed `ear`. Raw
 * equality first: a value equal to the placeholder is the one reading that cannot be told from it (`landingOf`'s
 * `placeholder`; fill-facts.ts#heldText).
 */
function showsExactly(observed: string, e: Expectation): boolean {
  const { value, clear } = e;
  if (isMaskedValue(observed)) return clear ? observed.length === value.length : observed.length >= heldCount(e) + value.length;
  return clear ? observed === value : observed === value || heldText(observed, e.placeholder).includes(value);
}

/** The bullets the field held after focus, an unread count as none. */
const heldCount = (e: Pick<Expectation, 'held'>): number => (e.held === 'unread' ? 0 : e.held);

/**
 * A masked reading of a field whose held count was never read (`'unread'`: said plain, the re-read skipped) — no length
 * of it but the typed one proves anything. `landingOf`'s `said-plain` and `differenceOf`'s `masked-said-plain`.
 */
const bulletsSaidPlain = (observed: string, e: Pick<Expectation, 'held'>): boolean => e.held === 'unread' && isMaskedValue(observed);

/** The text the typing lands after: the field's text before the typing (its placeholder aside), or none once cleared. */
// Stryker disable next-line StringLiteral: a cleared field's prior replaced by a text no reading starts with is tried, missed, and priorsOf falls back to none ('')
const priorText = (e: Pick<Expectation, 'clear' | 'before' | 'placeholder'>): string => (e.clear ? '' : heldText(e.before, e.placeholder));

/**
 * The texts a reading (`held`, its named placeholder aside) is judged after: the earlier text (`priorText`) — and,
 * without clear, when the reading's letters and digits do not START with the earlier text's (`skeleton`), no earlier
 * text as well, tried second: the earlier text VANISHED. Letters and digits, not the text as typed: a field that
 * regroups as it is typed shows an earlier `1,000` as `10,00…` once typed into, and that text is still there (D29
 * review round 1, MAJOR-1) — judged as the value alone, `10,001,000` would pass for a typed `10001000`.
 *
 * D29, measured on the owner's iOS run (SwiftUI lab, form-format's iban, f1 and f7): idb names no placeholder
 * (adapters/types.ts, UiNode.placeholder), so the UIKit field's placeholder `SK00 0000 0000 …` was read as the empty
 * field's value — `before` — and was gone at the first key; judged after it, the field holding `SK31 1200 0000` failed
 * "typed 12 characters but the field shows 14", and a dropped tail there was never typed again (D28). The fallback
 * reaches every source that names no placeholder — idb, and the API 33 uiautomator dump (a classic EditText's hint
 * dumped as its `text`; the Android lab's Compose fields dump no placeholder at all, so the lab is not affected) — and,
 * on both platforms, a field that REPLACES its earlier text on focus (a select-all): the reading cannot tell that from
 * an unnamed placeholder, and both are judged as the value alone.
 *
 * What it adds: a reading whose letters and digits do not start with the earlier text's may pass, or be retyped, as
 * the value alone, under `reformatOf`'s and `prefixOf`'s rules unchanged. A reading that starts with them is judged
 * after the earlier text, never without it. An earlier text with no letters or digits (a `—`, a `__/__/____` mask)
 * keeps the pre-D29 judgment — every reading starts with its empty skeleton — failing safe, as a false mismatch and
 * never a wrong pass: deliberately not loosened (D29 review round 2, MINOR-A). So does an unnamed placeholder whose
 * letters and digits are a prefix of the typed value's (a `+421` placeholder, `421903…` typed): the reading starts
 * with them, the fallback never runs, and the result is the old false mismatch.
 *
 * The earlier text is tried FIRST: a reading that is a prefix of the earlier text itself (`SK` of `SK00 …`) is then
 * that earlier text's prefix, nothing of the typing landed, and nothing is typed again; tried second, the same reading
 * would read as two typed characters and retype the rest. Pure.
 */
function priorsOf(held: string, e: Pick<Expectation, 'clear' | 'before' | 'placeholder'>): readonly string[] {
  const prior = priorText(e);
  // Stryker disable next-line ConditionalExpression,StringLiteral: an empty prior's skeleton starts every reading, so the guard changes nothing
  return prior !== '' && !skeleton(held).startsWith(skeleton(prior)) ? [prior, ''] : [prior];
}

/**
 * The reading `reformatOf` what the field should hold — its earlier text, unless cleared (or vanished: `priorsOf`,
 * D29), then the value — else undefined. D18, docs/adr/0034-a-fill-passes-a-field-that-reformats-as-it-is-typed.md.
 * A masked reading never is one (bullets are no typed characters). Pure.
 */
function landedReformat(observed: string, e: TextExpectation): Reformat | undefined {
  const held = heldText(observed, e.placeholder);
  for (const prior of priorsOf(held, e)) {
    const reformatted = reformatOf(held, prior + e.value);
    if (reformatted !== undefined) return reformatted;
  }
  return undefined;
}

/**
 * A reading that is a strict prefix of what the field should hold (`tailOf`): `missing` the rest, `landed` how many
 * characters of the TYPING the prefix holds (UTF-16 units, as a value's length is counted — 0 when only the field's
 * earlier text is there), `reformatted` when the field reformatted the prefix (separators added, spaces respaced).
 */
export interface Tail {
  missing: string;
  landed: number;
  reformatted?: Reformat;
}

/** Some of the typing is in the prefix: a tail the field dropped, not a typing that never reached it. */
const landedSome = (tail: Tail | undefined): tail is Tail => tail !== undefined && tail.landed > 0;

/**
 * What the field is missing of what it should hold (its text before the typing, unless cleared — or vanished, then
 * none: `priorsOf`, D29 — then the value), when its reading is a strict prefix of that — exactly or reformatted
 * (`prefixOf`, D28) — and shows no bullet: a `Tail`, else undefined. The one definition of a dropped tail: the typing
 * retypes it (`droppedTail`) and the verdict names it (`differenceOf`), so the two judge a prefix alike. Pure.
 */
export function tailOf(observed: string, e: TextExpectation): Tail | undefined {
  const held = heldText(observed, e.placeholder);
  const priors = priorsOf(held, e); // the earlier text first (`priorText`)
  if (hasBullet(held) || hasBullet(priors[0])) return undefined;
  for (const prior of priors) {
    const whole = prior + e.value;
    const shown = prefixOf(held, whole);
    if (shown === undefined) continue;
    const { prefix, reformatted } = shown;
    return { missing: whole.slice(prefix.length), landed: prefix.length - prior.length, ...(reformatted !== undefined && { reformatted }) };
  }
  return undefined;
}

/**
 * The characters the field dropped from the END of the typing (`tailOf`, with some of the typing landed: `landedSome`),
 * or undefined when its reading does not prove that. What fill-type.ts types again (ADR 0023). Pure.
 */
export function droppedTail(observed: string, e: TextExpectation): string | undefined {
  const tail = tailOf(observed, e);
  return landedSome(tail) ? tail.missing : undefined;
}

/**
 * What can be said of a reading that missed the value — ONE classification of the kinds (fill-facts.ts#Difference),
 * first match wins (2026-10-09, the fill-clear deepening; until then fill.ts chose `unchanged`, `masked` and the partly
 * masked `length` in a ternary at the throw, and a helper of its own the rest):
 * 0. `masked-said-plain`: a masked reading where the held count is `'unread'` (`landingOf`'s `said-plain`; one of the
 *    typed length lands, so it never gets here). Before `unchanged`: no reading of a field whose count was never
 *    read says more than that (A2, 2026-11-01; until then fill.ts built this Difference itself).
 * 1. `unchanged`: the reading is exactly what the field showed when typing began — whatever it is, bullets included
 *    (probes D and D2 were told "the app transformed the input").
 * 2. `masked`: bullets only, compared by length; `held` without clear.
 * 3. `length` of a PARTLY masked reading (Android's show-the-last-character password field, `•••••t`): its content is
 *    not comparable either (hasBullet: • and ● only — `*` and `·` are ordinary text too).
 * 4. `dropped-tail` (D28): the held text is a strict prefix of what the field should hold, grouped by the field
 *    (`tailOf`), with some of the typing in it — the tail dropped.
 * 5. Otherwise the HELD text is compared (a named placeholder is no text): with clear the field must EQUAL the value,
 *    so the two are compared whole; without, it must CONTAIN it, so every run of the new text (`typedPartOf`) as long
 *    as the value is compared and the closest one counts — `case` when one differs only in letter case, else
 *    `same-length` when the lengths match, else `length`. Only position-for-position: an inserted or dropped character
 *    is a length difference. Letter case by toLowerCase/toUpperCase of each UTF-16 unit — enough for the measured
 *    auto-capitalisation; a case pair whose forms differ in length (`ß`/`SS`) reads as a plain difference, never as a
 *    pass.
 * Pure, O(observed × value) — run once, for a typing that missed.
 */
export function differenceOf(observed: string, e: Pick<Expectation, keyof TextExpectation | 'held'>): Difference {
  const { value, clear } = e;
  if (bulletsSaidPlain(observed, e)) return { kind: 'masked-said-plain' };
  if (observed === e.before) return { kind: 'unchanged' };
  if (isMaskedValue(observed)) return { kind: 'masked', held: clear ? undefined : heldCount(e) };
  if (hasBullet(observed)) return { kind: 'length' };
  // D28: a reformatted strict prefix with some of the typing in it is a dropped tail, never "transformed".
  const tail = tailOf(observed, e);
  if (landedSome(tail) && tail.reformatted !== undefined) {
    return { kind: 'dropped-tail', landed: tail.landed, dropped: value.length - tail.landed, grouped: tail.reformatted.added > 0 };
  }
  const typed = typedPartOf(heldText(observed, e.placeholder), priorText(e));
  let caseOnly: number | undefined; // fewest case-only differing characters over the runs compared
  const starts = clear ? (typed.length === value.length ? [0] : []) : Array.from({ length: Math.max(0, typed.length - value.length + 1) }, (_, i) => i);
  for (const at of starts) {
    let differ = 0;
    let caseAlone = true;
    for (let i = 0; i < value.length && caseAlone; i++) {
      const a = typed[at + i];
      const b = value[i];
      if (a === b) continue;
      differ++;
      caseAlone = a.toLowerCase() === b.toLowerCase() || a.toUpperCase() === b.toUpperCase();
    }
    // Stryker disable next-line EqualityOperator: `<=` keeps the same count; differ 0 is a run equal to the value, which landed and is never judged here
    if (caseAlone && differ > 0 && (caseOnly === undefined || differ < caseOnly)) caseOnly = differ;
  }
  if (caseOnly !== undefined) return { kind: 'case', positions: caseOnly };
  if (typed.length !== value.length) return { kind: 'length' };
  let differ = 0;
  // Stryker disable next-line EqualityOperator: typed and value are as long here, so the index past both reads undefined on both sides
  for (let i = 0; i < value.length; i++) if (typed[i] !== value[i]) differ++;
  return { kind: 'same-length', positions: differ };
}

/**
 * What `differenceOf` compares of a held reading: what came AFTER the earlier text (`prior`), when the reading still
 * starts with it LITERALLY (typing appends at the cursor, which the focus tap leaves at the end), else the whole
 * reading — the limit: a run of the old text can then be named as the "transformed" typing.
 *
 * Deliberately not `priorsOf`'s letters-and-digits rule: a skeleton match cannot be sliced back to reading positions
 * (an earlier `1,000` that a regrouping field shows, with `5678` typed, as `10,005,678` starts with `1000` by its
 * letters and digits, but no slice of the reading is the typing), and an earlier text that vanished (D29) is compared
 * whole here as it is there. No input was found where the two rules give another Difference, and a Difference never
 * changes pass or fail — it words the failure.
 */
function typedPartOf(shown: string, prior: string): string {
  // Stryker disable next-line ConditionalExpression,StringLiteral: every text starts with an empty prior, and slicing off none is the text itself
  return prior !== '' && shown.startsWith(prior) ? shown.slice(prior.length) : shown;
}

/**
 * Whether the masked rule needs to know what the field held after focus — the post-focus re-read's question
 * (docs/adr/0028-a-fill-re-reads-after-focus-only-where-focus-can-change-the-count.md). Not for an EMPTY input its
 * source says is plain (UiNode.secure `false`; a named placeholder is empty, fill-facts.ts#heldText): it shows its
 * text, not bullets, so the reading compares content, which needs no count — and one that shows bullets after all
 * fails `said-plain` (`landingOf`). Everything else may hold bullets, or gain them on focus (an autofill). Pure.
 */
export const needsHeldCount = (f: Pick<UiNode, 'role' | 'secure' | 'value' | 'placeholder'>): boolean =>
  !(f.role === INPUT_ROLE && f.secure === false && heldText(f.value, f.placeholder) === '');

src/interact/fill-reformat.ts.source:
/**
 * The character rules of a field that reformats as it is typed — a pure leaf (D28 review, MINOR-2): whether a reading
 * is a typing with separators of the field's own added (`reformatOf`; D18,
 * docs/adr/0034-a-fill-passes-a-field-that-reformats-as-it-is-typed.md), whether it is a strict prefix of a typing,
 * exact or reformatted (`prefixOf`; D28, that ADR's amendment), and a text's letters and digits (`skeleton`). It knows
 * texts, not fields: which text a reading is judged against — the earlier text, the placeholder, clear — is
 * interact/fill-landing.ts's, its one caller. It imports only the facts (fill-facts.ts); nothing here types, reads a
 * device or words a sentence.
 */

import { isPoint, type Reformat } from './fill-facts.js';

/** The spaces a field may show for one another: a space, a no-break (U+00A0) and a narrow no-break (U+202F) space. */
const SPACES = new Set([' ', '\u00A0', '\u202F']);
/** What a formatting field may add between typed characters: the spaces, and `.` `,` `-` `/`. */
const SEPARATORS = new Set([...SPACES, '.', ',', '-', '/']);
// Stryker disable next-line Regex: only ever tested on one code point, where the anchors change nothing
const ALNUM = /^[\p{L}\p{N}]$/u;
const DIGIT = /\d/;
// Stryker disable next-line Regex: only ever tested on one code point, where the anchors change nothing
const LETTER = /^\p{L}$/u;
const DIGITS = /^\d+$/;

/**
 * The reading is `expected` — every character of it, in order — with ONE separator character the field added between
 * them (an IBAN grouped in fours, an amount's thousands, a date's slashes) and nothing else: `Reformat`, else undefined
 * (also for an exact reading, which the exact rule passes — a Reformat always counts at least one change). D18,
 * docs/adr/0034-a-fill-passes-a-field-that-reformats-as-it-is-typed.md. Tight, since a wrong pass is worse than a false
 * mismatch:
 * - every expected character is shown, in order and unchanged — a typed space may be shown as another space
 *   (`respaced`), nothing else may differ (letter case included); a separator that was typed must be shown: a field
 *   that dropped one (`12,50` → `1250`) changed the value;
 * - the added separators are all one character of SEPARATORS, each between two typed letters or digits: none
 *   leading (a `-` there is a sign), trailing, next to another, or after typed punctuation (`Hello, world` for
 *   `Hello,world` is an edit, not a format); between two LETTERS only when the typing is a code — digits in it and
 *   no typed space (an IBAN's `MALT MTLC`): in prose that is autocorrect splitting a word (`a lot` for `alot`);
 * - they cut the typing into groups of two or more characters, but for ONE single-character group at either end
 *   (`1 234`, an IBAN's last `1`): `1-5` for `15` is no grouping;
 * - an added `.` or `,` is a thousands separator: never a character the typing itself holds as `.` or `,`, the digits
 *   before the first one 1–3, not a lone `0` and not after a typed `.` or `,` (a fraction), exactly three between two
 *   of them and after the last (then no digit). That rules out a cents mask's `1.25` for `125` and `0.123` for `0123`, but not every decimal point: `1.234`
 *   for `1234` is de-DE's thousands or a three-decimal mask, which the reading cannot tell — so the verdict passes it
 *   with a caveat (`point`), not silently.
 * Greedy: a reading character equal to the next expected one is taken as that character. Taken as an added separator
 * instead, the expected one would have to match a later, equal character — so matching first never rejects what
 * skipping would pass but under the grouping rules, where the miss is a false mismatch (the safe side). Pure,
 * O(reading).
 *
 * `typing` (D28): the whole typing whose character classes decide the code rule and the thousands rule — `expected`
 * itself, unless the reading is judged as a PREFIX of a typing (`prefixOf`): the prefix of a typing that holds a space
 * or a `,` must not pass what the whole typing would refuse.
 */
export function reformatOf(observed: string, expected: string, typing: string = expected): Reformat | undefined {
  // Code points on both sides (an astral letter is one character, not two UTF-16 units).
  const expectedChars = [...expected];
  const typingChars = [...typing];
  // A code: digits in it and no typed space (an IBAN, a card number) — the one typing whose letters a field may split.
  const code = typingChars.some((c) => DIGIT.test(c)) && !typingChars.some((c) => SPACES.has(c));
  const walked = walk(observed, expectedChars);
  if (walked === undefined || walked.matched !== expectedChars.length) return undefined;
  const { tokens, respaced } = walked;
  const chars = [...observed];
  const added = new Set(chars.filter((_, k) => tokens[k] === -1));
  if (added.size > 1) return undefined;
  const sep = [...added][0];
  // Each added separator between two typed letters or digits; the groups between them.
  const groups: number[] = [0];
  for (let k = 0; k < tokens.length; k++) {
    if (tokens[k] !== -1) {
      groups[groups.length - 1]++;
      continue;
    }
    // Both neighbours typed letters or digits: none leading or trailing (no neighbour), none next to another added
    // one (-1), none after typed punctuation.
    // Stryker disable next-line ConditionalExpression,LogicalOperator: expectedChars[undefined] and expectedChars[-1] are undefined, which ALNUM never matches
    const typedAlnum = (t: number | undefined) => t !== undefined && t !== -1 && ALNUM.test(expectedChars[t]);
    if (!typedAlnum(tokens[k - 1]) || !typedAlnum(tokens[k + 1])) return undefined;
    // Between two LETTERS only in a code (round 2, MAJOR-A): in prose a space or `-` added there is autocorrect
    // splitting a word (`a lot` for `alot`, `jo-hn@x.com`), not a format; an IBAN's `MALT MTLC` is.
    const letter = (t: number) => LETTER.test(expectedChars[t]);
    if (!code && letter(tokens[k - 1]) && letter(tokens[k + 1])) return undefined;
    groups.push(0);
  }
  const singles = groups.map((n, k) => (n < 2 ? k : -1)).filter((k) => k !== -1);
  const atAnEnd = (k: number) => k === 0 || k === groups.length - 1;
  if (singles.length > 1 || (singles.length === 1 && !atAnEnd(singles[0]))) return undefined;
  const point = isPoint(sep) ? sep : undefined;
  if (point !== undefined && !thousands(chars, tokens, typing, point)) return undefined;
  const count = groups.length - 1;
  if (count + respaced === 0) return undefined;
  return { added: count, respaced, ...(point !== undefined && { point }) };
}

/**
 * The reading walked against `expectedChars`, greedily (see `reformatOf`): each reading character the next expected one
 * (or a space shown for a typed space — `respaced`), else an added separator (-1 in `tokens`, an expected character's
 * index otherwise); undefined at the first character that is neither. `matched`: how many expected characters it
 * showed — all of them for `reformatOf`, fewer for a prefix (`prefixOf`). The one walk both ask.
 */
function walk(observed: string, expectedChars: readonly string[]): { tokens: number[]; matched: number; respaced: number } | undefined {
  const tokens: number[] = [];
  let j = 0;
  let respaced = 0;
  for (const c of observed) {
    const next = expectedChars[j];
    if (c === next) tokens.push(j++);
    else if (next !== undefined && SPACES.has(c) && SPACES.has(next)) {
      tokens.push(j++);
      respaced++;
    } else if (SEPARATORS.has(c)) tokens.push(-1);
    else return undefined;
  }
  return { tokens, matched: j, respaced };
}

/** An added `.` or `,` groups digits by thousands (see `reformatOf`); `typing` the whole typing. */
function thousands(chars: string[], tokens: number[], typing: string, point: string): boolean {
  // The typing holds this character itself (its decimal point, or its own grouping): an added one is no thousands mark.
  if (typing.includes(point)) return false;
  const marks = tokens.flatMap((t, k) => (t === -1 ? [k] : []));
  let start = marks[0] - 1;
  while (start >= 0 && DIGIT.test(chars[start])) start--;
  // The digits before the first mark are a whole part, not a fraction after a typed point (`0,12.345`; round 2).
  if (start >= 0 && isPoint(chars[start])) return false;
  const lead = chars.slice(start + 1, marks[0]).join('');
  if (!DIGITS.test(lead) || lead.length > 3 || lead === '0') return false;
  for (let n = 0; n < marks.length; n++) {
    const end = n + 1 < marks.length ? marks[n + 1] : marks[n] + 4;
    const run = chars.slice(marks[n] + 1, end).join('');
    if (run.length !== 3 || !DIGITS.test(run)) return false;
    // Stryker disable next-line ConditionalExpression,LogicalOperator: before the last mark chars[end] is the next mark, and past the reading undefined, neither a digit
    if (n + 1 === marks.length && chars[end] !== undefined && DIGIT.test(chars[end])) return false;
  }
  return true;
}

/** A text's letters and digits alone (`ALNUM`), in order: what a field that regroups it keeps of it. */
export const skeleton = (text: string): string => [...text].filter((c) => ALNUM.test(c)).join('');

/**
 * The strict prefix of `whole` a reading shows: exactly, or — D28 — REFORMATTED (`reformatOf` of the prefix, its
 * rules judged over the whole typing: one separator kind, letters split only in a code, an added `.`/`,` only as a
 * thousands mark the typing does not hold itself). The prefix is the typed characters the reading shows, in order —
 * `walk`, the greedy walk `reformatOf` takes, every other reading character an added separator; nothing else may differ.
 * Undefined when the reading is no strict prefix (the whole of it, more, or other text). Pure, O(reading).
 */
export function prefixOf(held: string, whole: string): { prefix: string; reformatted?: Reformat } | undefined {
  if (held.length < whole.length && whole.startsWith(held)) return { prefix: held };
  const wholeChars = [...whole];
  const walked = walk(held, wholeChars);
  if (walked === undefined || walked.matched >= wholeChars.length) return undefined;
  const prefix = wholeChars.slice(0, walked.matched).join('');
  const reformatted = reformatOf(held, prefix, whole);
  return reformatted === undefined ? undefined : { prefix, reformatted };
}

src/interact/fill-verdict.ts.source:
/**
 * What a fill's facts MEAN, decided once, as codes — never as sentences.
 *
 * interact/fill.ts measures (`FillResult`: what the clear deleted, how the
 * read-back went, what the node is, what the masked field held). Two media
 * report it: the MCP type_text reply and the flow's `fill` trace line. Until
 * 2026-10-09 each of them asked the facts its own questions — "is it
 * verified" was `fillUnverifiedText(...) === undefined` in both, "what did
 * the clear send" was `fillClearedText`, whose answer depended on the first
 * question, and the reply alone had a third branch (`clearAloneHead`) for a
 * clear with nothing typed. The two media drifted on exactly that seam: a
 * clear alone that was not verified read `(N deletes sent)` on one and
 * `cleared N characters first` on the other until df8a91a
 * (docs/bugs/2026-10-08-ios-fill-unverified-reports-filled-and-cleared.md).
 *
 * Now the split is three-way, each part with one owner:
 * - facts — interact/fill-facts.ts#FillResult, measured by fill.ts, never
 *   worded (the masked-append warning was a sentence on the result until
 *   2026-10-09; it is `maskedAppend: { held }` now, and its sentence a row
 *   in fill-text.ts);
 * - judgement — `judgeFill` here: the head verb (`did`), what the clear
 *   sent and how to count it (`sent`), WHY the fill is not verified
 *   (`reasons`, codes) and what else the caller must hear (`caveats`,
 *   codes). Pure, total, no I/O; the tests of the judgement assert codes,
 *   never wording;
 * - words — interact/fill-text.ts's, all of them: the sentence tables
 *   (one row per code, exhaustive, so a new code without its sentence does
 *   not compile) and the layout of both media beside them. The same rule as
 *   scroll_until's (interact/scroll-rounds.ts judges into typed outcomes,
 *   interact/scroll-text.ts says every sentence): the judge emits codes, the
 *   renderer owns the words. Until 2026-10-09 (code review S1) the tables
 *   sat here and only the layout was fill-text.ts's.
 *
 * The verdict's invariants (pinned in tests/interact/fill-verdict.test.ts):
 * - `did === 'filled'` ⇔ `reasons.length === 0` — "Filled" is the only
 *   verified head, and an unverified fill always says why.
 * - Unverified: `did` is `'typed'` ⇔ `typed > 0`; with `typed === 0` it is
 *   `'cleared'` ⇔ a delete went out (`sent` present), else `'focused'`.
 * - `sent` is present ⇔ there is something true to say: characters the
 *   clear was seen to delete (`cleared` > 0), or — for a clear alone that
 *   is not verified — deletes that went out (`clearUnchanged.deletes`, all
 *   rounds, else `cleared`); it counts `deletes` ⇔ `did === 'cleared'` (nothing typed
 *   after it and nothing seen empty, so "cleared … first" would claim both a
 *   result and a sequel that never came — code review of round 2,
 *   2026-10-08), `characters` otherwise.
 * - `reasons` order is render order: the read-back's reason (`no-value`,
 *   `not-taken`, `lost`, `placeholder`) first, then the clear's
 *   (`clear-unmeasured`, `clear-unchanged`, `clear-no-length` — at most one), never when the
 *   read-back `landed` — with clear, `landed` is "the field shows exactly
 *   the value", which is what the clear was for. A clear ALONE (nothing
 *   typed, read-back `nothing-typed`) that stopped on unchanged deletes is
 *   therefore unverified: `cleared` in deletes, its reason the only one.
 * - `caveats` order: the not-an-input finding, then the masked-append
 *   warning, then a reformat's added point. fill.ts never produces two of
 *   them together: a not-input finding needs a read-back that did not land,
 *   and the other two a landed one — a masked-append an input whose masked
 *   reading took the text, a reformatted point a plain reading (a masked one
 *   is never a reformat).
 *
 * It judges facts, never a reading: what a read-back that missed the value
 * differs by (`Difference`) is interact/fill-landing.ts#differenceOf's,
 * carried in the mismatch FillFailure (A2, 2026-11-01; until then
 * `differenceOf` lived here).
 *
 * Its one import is the facts (interact/fill-facts.ts, a leaf). It imports
 * neither fill.ts, which measures, nor fill-text.ts, which reads the
 * verdict — the graph is fill.ts → fill-facts.ts ← fill-verdict.ts ←
 * fill-text.ts, and fill.ts → fill-text.ts for its errors' words.
 */

import { hasPoint, type FillResult, type LostWhy, type NearbyInput, type PointedReformat, type Reformat } from './fill-facts.js';

/**
 * Why a fill is NOT verified — one code per reason, in render order:
 * - `no-value`: the node was found, is not an input, and exposed no value
 *   on the last read; nothing was compared (ReadBack `no-value`).
 * - `not-taken`: the node is not an input and its value never showed the
 *   text — not the field (ReadBack `not-taken`).
 * - `lost`: the field itself was not found again, `why` says how; said as
 *   the field's absence, never as the node's lack of a value — the node may
 *   well hold the text (ReadBack `lost`).
 * - `clear-unmeasured`: the clear sent no delete because the node is not
 *   the input, so its length is not the field's (`cleared: 'unmeasured'`).
 * - `clear-no-length`: the clear sent no delete because the node gave no
 *   length at all (`cleared: 0` on a `no-value` read-back).
 * - `placeholder`: the field shows exactly its named placeholder — empty,
 *   or holding that very text: the read-back after typing (ReadBack
 *   `placeholder`), or a clear alone that ended on it without seeing the
 *   field empty (`clearPlaceholder` `shown` or `prefix`; never `other`).
 *   Decided here since 2026-10-09 (the fill-clear deepening): until then
 *   fill.ts folded seven conditions into a `placeholder` read-back of its
 *   own for the clear alone.
 * - `clear-unchanged`: the clear's last deletes left the field showing the
 *   same `shows` characters (`clearUnchanged`) — its hint or placeholder
 *   on an empty field, or a field ignoring deletes; nothing saw it empty.
 */
export type Reason =
  | { code: 'no-value'; role: string }
  | { code: 'not-taken'; role: string }
  | { code: 'lost'; why: LostWhy }
  | { code: 'clear-unmeasured'; role: string }
  | { code: 'placeholder' }
  | { code: 'clear-no-length' }
  | { code: 'clear-unchanged'; shows: number };

/** What the clear SENT — never what was asked (2026-10-08) — and in which unit it is said (see the module header's invariants). */
export interface Sent {
  what: 'characters' | 'deletes';
  n: number;
}

/**
 * What the caller must hear beside the verdict, on lines of their own:
 * - `not-input`: the matched node is not a textfield and the read-back did
 *   not show the text in it; `input` is the nearest input (`none`: the
 *   screen has none; `unread`: the tree to look in could not be read);
 *   `typed`: whether anything was typed (a focus-and-clear alone says what
 *   was NOT deleted instead of where typing went).
 * - `masked-append`: a masked field held `held` characters after focus and
 *   clear was off — the length rule cannot tell the append from a correct
 *   fill (finportal 2026-09-17: backend `invalid_grant`).
 * - `reformatted-point` (D18, the orchestrator's decision of review round 1):
 *   the field showed the typing reformatted with an added `.` or `,` — a
 *   thousands separator by its place, but the reading cannot tell it from a
 *   decimal point (`1.234` for `1234`: de-DE, or a three-decimal mask). The
 *   fill passes, the reformat said here instead of the aside.
 */
export type Caveat =
  | { code: 'not-input'; role: string; typed: boolean; input: NearbyInput | 'none' | 'unread' }
  | { code: 'masked-append'; held: number }
  | { code: 'reformatted-point'; reformat: PointedReformat };

/** A fill, judged. Built only by `judgeFill`; its invariants are the module header's. */
export interface FillVerdict {
  /** The head verb: what the fill can be said to have done. */
  did: 'filled' | 'typed' | 'cleared' | 'focused';
  /** The length of the text typed — a length, never content. */
  typed: number;
  /** Absent when no delete went out (`cleared` undefined, 0 or `'unmeasured'`). */
  sent?: Sent;
  /** `[]` ⇔ `did === 'filled'` — the only way to say "verified". */
  reasons: Reason[];
  caveats: Caveat[];
  /** The dropped tails typed again before the read-back landed, by length (FillResult.retyped); absent when none. */
  retyped?: number[];
  /**
   * The field showed the typing reformatted, separators of its own added (FillResult.reformatted, D18): still filled.
   * Only a reformat without a `point` — one with is the `reformatted-point` caveat instead.
   */
  reformatted?: Reformat;
  /** The resolution note (resolve.ts#resolveNow), carried for the MCP reply; the flow line prints none. */
  note?: string;
}

/**
 * Judge a fill from its facts. Pure, total, O(1): it runs once per fill,
 * after every device read is done. The one place that decides "verified",
 * the head verb and the deletes-vs-characters unit — renderers read the
 * result and decide none of it.
 */
export function judgeFill(r: FillResult): FillVerdict {
  const { readBack, role, cleared, typed } = r;
  const reasons: Reason[] = [];
  if (readBack.kind === 'no-value') reasons.push({ code: 'no-value', role });
  if (readBack.kind === 'not-taken') reasons.push({ code: 'not-taken', role });
  if (readBack.kind === 'lost') reasons.push({ code: 'lost', why: readBack.why });
  if (readBack.kind === 'placeholder' || (readBack.kind === 'nothing-typed' && clearSawNoEmpty(r.clearPlaceholder))) reasons.push({ code: 'placeholder' });
  if (readBack.kind !== 'landed') {
    if (cleared === 'unmeasured') reasons.push({ code: 'clear-unmeasured', role });
    else if (r.clearUnchanged !== undefined) reasons.push({ code: 'clear-unchanged', shows: r.clearUnchanged.shows });
    else if (cleared === 0 && readBack.kind === 'no-value') reasons.push({ code: 'clear-no-length' });
  }
  const verified = reasons.length === 0;
  // Characters: what the clear was SEEN to delete (`cleared`). Deletes:
  // what went out, all rounds — said only of a clear alone nobody saw land,
  // where the deletes are all there is to report.
  // Stryker disable next-line ConditionalExpression: 'unmeasured' or undefined in place of 0 is no number > 0 either, so `sent` is the same
  const characters = typeof cleared === 'number' ? cleared : 0;
  const deletes = r.clearUnchanged?.deletes ?? characters;
  const sent: Sent | undefined =
    typed === 0 && !verified
      ? deletes > 0
        ? { what: 'deletes', n: deletes }
        : undefined
      : characters > 0
        ? { what: 'characters', n: characters }
        : undefined;
  const caveats: Caveat[] = [];
  if (r.notInput !== undefined) caveats.push({ code: 'not-input', role, typed: readBack.kind !== 'nothing-typed', input: r.notInput.input });
  if (r.maskedAppend !== undefined) caveats.push({ code: 'masked-append', held: r.maskedAppend.held });
  const { reformatted } = r;
  if (reformatted !== undefined && hasPoint(reformatted)) caveats.push({ code: 'reformatted-point', reformat: reformatted });
  return {
    did: verified ? 'filled' : typed > 0 ? 'typed' : sent !== undefined ? 'cleared' : 'focused',
    typed,
    sent,
    reasons,
    caveats,
    ...(r.retyped !== undefined && r.retyped.length > 0 && { retyped: r.retyped }),
    ...(reformatted !== undefined && !hasPoint(reformatted) && { reformatted }),
    note: r.note,
  };
}

/**
 * A clear that ended on exactly the named placeholder did NOT see the field
 * empty when the placeholder was there before any delete (`shown`: nothing
 * was deleted, so nothing was seen go) or the last deletes went into a
 * reading that started with its text (`prefix`: deletes go from the end, so
 * `Companyabc` with 3 of 10 landing leaves `Company` — review round 2,
 * probe K). From any other reading (`other`) the placeholder can only be
 * the field showing empty, and the clear is verified. Only a clear alone
 * asks (read-back `nothing-typed`): with a value, the exact read-back
 * decides.
 */
const clearSawNoEmpty = (end: FillResult['clearPlaceholder']): boolean => end === 'shown' || end === 'prefix';

