/**
 * A later STACKED screen-sized layer covers the screen beneath it through its OWN surface, when the layer carries
 * content (docs/adr/0018-a-later-stacked-screen-layer-covers-the-screen-beneath.md): a node `structural`, `screenSizedHost` or `contentFramed` would excuse by its frame still covers a target
 * when, below the node holding both — inside one window — it lies in a screen-sized layer and the target in another
 * (`stackedScreens`, asked of the node), and the layer carries something drawable; a bare frame of the layer stays
 * excused. Measured on device ui_snapshots (tests/fixtures/wda-ui-snapshot-stacked-layers.json).
 */
describe('exposure — a later stacked screen layer covers the screen beneath through its own surface (ADR 0018)', () => {
  const IPHONE = rect(0, 0, 402, 874);
  const screen = (key: string) => STACKED.screens[key];
  const byId = (tree: UiNode, id: string) => [...everyNode(tree)].find((n) => n.identifier === id || n.label === id)!;
  /** An unidentified, unlabelled, unvalued `container` leaf — a bare frame. */
  const bareFrame = (n: UiNode) => n.role === 'container' && n.children.length === 0 && !n.identifier && !n.label && !n.value;

  it('measured, Finportal\'s RN transparent Modal (#248): lang_sk shows nothing — the dimming leaf `forgot_overlay` is on top at its centre; the layer\'s bare frames are no cover', () => {
    const tree = screen('finportalForgot');
    const seen = drawOrder(tree).exposure(byId(tree, 'lang_sk'), IPHONE);
    expect(seen.shows).toBe(0);
    expect(seen.centreCover?.node.identifier).toBe('forgot_overlay');
    expect(coverNodes(seen.covers).filter(bareFrame)).toEqual([]);
    expect(seen.tapAt).toBeUndefined();
  });

  it('measured, Contacts\' New Contact page sheet (#146, #150): the list\'s photo buttons show nothing — the sheet\'s form `scrollable 0,62 402x812` is on top at Kate Bell\'s; the dimming leaf `-402,-874 1206x2622` is no cover', () => {
    for (const [key, label] of [['contactsSheet', 'Contact photo for Kate Bell'], ['contactsSheetScrolled', 'Contact photo for Hank M. Zakroff']] as const) {
      const tree = screen(key);
      const seen = drawOrder(tree).exposure(byId(tree, label), IPHONE);
      expect(seen.shows).toBe(0);
      expect(coverNodes(seen.covers).filter(bareFrame)).toEqual([]);
    }
    const tree = screen('contactsSheet');
    expect(drawOrder(tree).exposure(byId(tree, 'Contact photo for Kate Bell'), IPHONE).centreCover?.node).toMatchObject({ role: 'scrollable', rect: rect(0, 62, 402, 812) });
  });

  it('no regression, measured: the layer\'s own nodes, and every node of the login screen with no modal (#218), read uncovered', () => {
    const coveredOf = (tree: UiNode, keep: (n: UiNode) => boolean) => {
      const order = drawOrder(tree);
      return [...everyNode(tree)].filter((n) => keep(n) && rectWithin(n.rect, IPHONE) && n.rect.width * n.rect.height > 0 && (isInteractive(n) || n.label) && order.exposure(n, IPHONE).covers.length > 0).map((n) => n.identifier ?? n.label);
    };
    expect(coveredOf(screen('finportalLogin'), () => true)).toEqual([]);
    expect(coveredOf(screen('finportalForgot'), (n) => n.identifier?.startsWith('forgot_') === true)).toEqual([]);
  });

  it('no regression, measured: Safari (#158, page B, reached by `tap role:text text:"Go to page B"` measured Tapped at #157) — no node of the web view reads covered by `CapsuleViewController 0,0 402x874`, the later full-screen layer that draws only its bottom bar', () => {
    const tree = screen('safariPageB');
    const order = drawOrder(tree);
    const capsule = byId(tree, 'CapsuleViewController');
    const web = [...everyNode(tree)].find((n) => n.role === 'webview' && n.identifier === 'WebView')!;
    const underCapsule = [...everyNode(web)]
      .filter((n) => n.rect.width * n.rect.height > 0 && rectWithin(n.rect, IPHONE))
      .filter((n) => order.exposure(n, IPHONE).covers.some(({ node: c }) => c === capsule || [...everyNode(capsule)].includes(c) && rectArea(c.rect) >= rectArea(IPHONE) * 0.9));
    expect(underCapsule.map((n) => n.identifier ?? n.label ?? n.role)).toEqual([]);
    expect(coverNodes(order.exposure(byId(tree, 'Link number 1'), IPHONE).covers)).toEqual([]);
  });

  describe('the rule\'s edges, on synthetic trees', () => {
    const pay = () => uiNode({ role: 'button', label: 'Pay', rect: rect(24, 700, 354, 50) });
    const card = () => uiNode({ role: 'text', label: 'Reset account', rect: rect(16, 301, 370, 220) });
    /** One window: the screen beneath (a full-screen layer holding `target`), then `layer`. */
    const window = (target: UiNode, layer: UiNode) =>
      uiNode({ role: 'container', label: 'MyPort', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [target] }), layer] })] });
    const covers = (tree: UiNode, target: UiNode) => coverNodes(drawOrder(tree).exposure(target, IPHONE).covers);

    it('only surfaces that draw their whole rect give way: a scroll view carrying its rows and a structural LEAF cover; an unlabelled wrapper or a screen-sized host WITH children stays excused — it may be a pass-through layer (Safari\'s `CapsuleViewController`)', () => {
      const scroll = uiNode({ role: 'scrollable', rect: rect(0, 62, 402, 812), children: [card()] });
      const leaf = uiNode({ role: 'container', identifier: 'forgot_overlay', rect: IPHONE });
      for (const surface of [scroll, leaf]) {
        const target = pay();
        const layer = uiNode({ role: 'container', rect: IPHONE, children: [surface, card()] });
        expect(covers(window(target, layer), target)).toEqual([surface]);
      }
      const wrapper = uiNode({ role: 'container', rect: IPHONE, children: [card()] });
      const host = uiNode({ role: 'toolbar', rect: IPHONE, children: [card()] });
      for (const layer of [wrapper, host]) {
        const target = pay();
        expect(covers(window(target, layer), target)).toEqual([]);
      }
    });

    it('a leaf gives way only when it fills the screen: a small leaf of the layer over the target — an icon\'s `other`, a named view — stays excused and is no presented surface (an Android logo\'s parts, a Snackbar host\'s icon)', () => {
      for (const leaf of [uiNode({ role: 'other', rect: rect(30, 705, 40, 40) }), uiNode({ role: 'container', identifier: 'snackbar_icon', rect: rect(30, 705, 40, 40) })]) {
        const target = pay();
        const seen = drawOrder(window(target, uiNode({ role: 'container', rect: IPHONE, children: [leaf, card()] }))).exposure(target, IPHONE);
        expect(seen).toMatchObject({ covers: [] });
      }
    });

    it('a bare frame of the layer stays excused; a leaf the app named (the dimming root `forgot_overlay`) covers', () => {
      const target = pay();
      const bare = uiNode({ role: 'container', rect: IPHONE });
      const overlay = uiNode({ role: 'container', identifier: 'forgot_overlay', rect: IPHONE });
      const layer = uiNode({ role: 'container', rect: IPHONE, children: [overlay, bare, card()] });
      expect(covers(window(target, layer), target)).toEqual([overlay]);
    });

    it('`presented` marks the presented screen\'s surfaces — a structural leaf filling the screen, labelled or not (UIKit\'s `PopoverDismissRegion` \'dismiss popup\', the dim of a half sheet and of a popover), a scroll view — never a control of the layer (Safari\'s capsule bar, or a backdrop button filling the screen) nor a labelled leaf smaller than the screen, whose sentence stays "scroll_until it first"', () => {
      const target = pay();
      const dim = uiNode({ role: 'other', rect: IPHONE });
      const dismissRegion = uiNode({ role: 'container', label: 'dismiss popup', identifier: 'PopoverDismissRegion', rect: rect(-402, -874, 1206, 2622) });
      const labelledBanner = uiNode({ role: 'other', label: 'Address', rect: rect(0, 650, 402, 150) });
      const button = uiNode({ role: 'button', label: 'Back', rect: rect(24, 700, 48, 48) });
      const order = (...surface: UiNode[]) => tagged(drawOrder(window(target, uiNode({ role: 'container', rect: IPHONE, children: [...surface, card()] }))).exposure(target, IPHONE).covers);
      expect(order(dim)).toEqual([{ node: dim, order: 'drawn', presented: true }]);
      expect(order(dismissRegion)).toEqual([{ node: dismissRegion, order: 'drawn', presented: true }]);
      const namedDim = uiNode({ role: 'other', label: 'Close dialog', rect: IPHONE }); // any label, not UIKit's only: an RN dim given an accessibilityLabel
      expect(order(namedDim)).toEqual([{ node: namedDim, order: 'drawn', presented: true }]);
      expect(order(labelledBanner, button)).toEqual([
        { node: labelledBanner, order: 'drawn', presented: false },
        { node: button, order: 'drawn', presented: false },
      ]);
      const backdrop = uiNode({ role: 'button', label: 'Close', rect: IPHONE }); // a control filling the screen (an RN Pressable backdrop): a cover of its own, not a structural leaf
      expect(order(backdrop)).toEqual([{ node: backdrop, order: 'drawn', presented: false }]);
    });

    it('a labelled screen-filling leaf of the target\'s OWN screen is a cover and no presented surface: the exception asks for a later screen stacked over the target\'s', () => {
      const target = pay();
      const dismissRegion = uiNode({ role: 'container', label: 'dismiss popup', identifier: 'PopoverDismissRegion', rect: IPHONE });
      const tree = uiNode({ role: 'container', label: 'MyPort', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [target, dismissRegion, card()] })] })] });
      expect(tagged(drawOrder(tree).exposure(target, IPHONE).covers)).toEqual([{ node: dismissRegion, order: 'drawn', presented: false }]);
    });

    it('a layer carrying nothing drawable stays excused: empty frames only, an itemless toolbar (WDA\'s `toolbar \'Toolbar\'` host, as Finportal and SwiftUI list it), or a layer that is itself the dimming node — a leaf the app named, an `other` over empty frames — with no card in it', () => {
      const frames = uiNode({ role: 'container', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE })] })] });
      const toolbarHost = uiNode({ role: 'container', rect: IPHONE, children: [uiNode({ role: 'toolbar', label: 'Toolbar', identifier: 'Toolbar', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE })] })] });
      const namedDim = uiNode({ role: 'container', identifier: 'forgot_overlay', rect: IPHONE });
      const dimOther = uiNode({ role: 'other', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE })] });
      for (const layer of [frames, toolbarHost, namedDim, dimOther]) {
        const target = pay();
        expect(covers(window(target, layer), target)).toEqual([]);
      }
    });

    it('only inside one window: the same layer as a later WINDOW, a child of the root, covers only through its content — a pass-through window (the parked input-accessory Window, wda-source-myport-2fa-keyboard-parked.json, its Done toolbar at the bottom)', () => {
      const target = pay();
      const done = uiNode({ role: 'toolbar', label: 'Toolbar', rect: rect(0, 826, 402, 48), children: [uiNode({ role: 'button', label: 'Done', rect: rect(317, 831, 64, 38) })] });
      const accessoryWindow = uiNode({ role: 'container', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [done] })] });
      const tree = uiNode({ role: 'container', label: 'MyPort', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [target] })] }), accessoryWindow] });
      expect(covers(tree, target)).toEqual([]);
    });

    it('not in scrolled content: layers of one scroll view\'s content are one screen — measured, Finportal\'s RN ScrollView (#218): its full-screen background container\'s `0,0 402x102` frame, under the later `0,0 402x877` content container, has nothing over it; synthetic, a header image in the same shape under a leaf of the content layer', () => {
      const login = screen('finportalLogin');
      const header = [...everyNode(login)].find((n) => n.role === 'container' && n.rect.height === 102)!;
      expect(coverNodes(drawOrder(login).exposure(header, IPHONE).covers)).toEqual([]);
      const image = uiNode({ role: 'image', label: 'Header', rect: rect(0, 0, 402, 102) });
      const gradient = uiNode({ role: 'other', rect: rect(0, 0, 402, 877) }); // a screen-filling leaf of the content layer over the header: a surface, were the layers two screens
      const content = uiNode({ role: 'container', rect: rect(0, 0, 402, 877), children: [gradient, card()] });
      const scroll = uiNode({ role: 'scrollable', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [image] }), content] });
      const tree = uiNode({ role: 'container', label: 'MyPort', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [scroll] })] });
      expect(covers(tree, image)).toEqual([]);
    });

    it('not two screens: a target with no screen-sized layer of its own below the node holding both (a bar\'s button, a backdrop directly in it) — the later layer\'s frame is judged as before', () => {
      const back = uiNode({ role: 'button', label: 'Back', rect: rect(16, 62, 44, 44) });
      const bar = uiNode({ role: 'container', rect: rect(0, 62, 402, 54), children: [back] });
      const content = uiNode({ role: 'container', rect: IPHONE, children: [card()] });
      const tree = uiNode({ role: 'container', label: 'MyPort', rect: IPHONE, children: [uiNode({ role: 'container', rect: IPHONE, children: [bar, content] })] });
      expect(covers(tree, back)).toEqual([]);
    });
  });
});

/**
 * Where a stroke for a target would touch down, asked on the target's behalf: is that point on a surface of a screen
 * presented over the target's own (`presentedSurface`, ADR 0018)? `scroll_until` asks it before every stroke for a
 * target it has not judged in the viewport — one below the fold has no covers (`exposure` judges only what shows), so
 * the presented stop of a target in the viewport never sees it, and the stroke lands on the presented screen. Measured
 * on device ui_snapshots (tests/fixtures/wda-ui-snapshot-stacked-layers.json) and one raw /source capture
 * (tests/fixtures/wda-capture-contacts-discard-popover.json).
 */
describe('presentedAt — the presented screen\'s surface at a point, asked for a target wherever it lies (ADR 0018)', () => {
  const screen = (key: string) => STACKED.screens[key];
  const find = (tree: UiNode, keep: (n: UiNode) => boolean) => [...everyNode(tree)].find(keep)!;
  /** The touch-down of a 60 % stroke down over the 402x874 screen (stroke-plan.ts#scrollStroke). */
  const TOUCH_DOWN = { x: 201, y: 699 };

  it('measured, Contacts\' discard popover with the keyboard down: the sheet\'s cell "add instant message" at y 1306, below the fold, has no covers — and the stroke\'s touch-down lies on the action sheet WDA types in the popover\'s layer, reaching the whole screen (not on the popover\'s own dim, a node of that layer)', () => {
    const tree = DISCARD_POPOVER_KEYBOARD_DOWN;
    const cell = find(tree, (n) => n.role === 'container' && n.label === 'add instant message');
    const order = drawOrder(tree);
    expect(order.exposure(cell, IPHONE_BOX)).toMatchObject({ covers: [] });
    const surface = order.presentedAt(cell, TOUCH_DOWN)!;
    expect(surface).toMatchObject({ label: 'Are you sure you want to discard this new contact?', rect: rect(10, 78, 240, 169) });
    expect(order.presentation.press(surface)).toMatchObject({ reach: IPHONE_BOX, layer: { kind: 'actionSheet', label: 'Are you sure you want to discard this new contact?' } });
  });

  it('measured, the SWIFT form under the Fees half sheet: `payee_city_input` at y 937 — the last surface at the point is named, the sheet\'s form `scrollable 31,456 340x355` over the dim `-402,-874 1206x2622`; above the sheet only the dim', () => {
    const tree = screen('swiftFeesSheet');
    const field = find(tree, (n) => n.identifier === 'swift_payment.form.payee_city_input');
    const order = drawOrder(tree);
    expect(order.presentedAt(field, TOUCH_DOWN)).toMatchObject({ role: 'scrollable', rect: rect(31, 456, 340, 355) });
    expect(order.presentedAt(field, { x: 201, y: 175 })).toMatchObject({ label: 'dismiss popup', rect: rect(-402, -874, 1206, 2622) });
  });

  it('a target of the presented screen itself is stroked on its own screen: the page sheet\'s cell "add url" below its fold, at the same point on the sheet\'s form — none', () => {
    const tree = screen('contactsSheet');
    const cell = find(tree, (n) => n.role === 'container' && n.label === 'add url');
    expect(drawOrder(tree).presentedAt(cell, TOUCH_DOWN)).toBeUndefined();
  });

  it('residual, measured on the Fees half sheet: a node of the screen beneath with the SAME frame as a presented surface — the hidden twin `PopoverDismissRegion` listed in the SWIFT form\'s own layer — is not asked about the real dim at a point both hold: the target column excuses a node of the target\'s own frame (`sameFrame`), so none is named; the sheet\'s form below the dim still is', () => {
    const tree = screen('swiftFeesSheet');
    const [twin, dim] = [...everyNode(tree)].filter((n) => n.label === 'dismiss popup');
    expect(twin.rect).toEqual(dim.rect);
    const order = drawOrder(tree);
    expect(order.presentedAt(twin, { x: 201, y: 175 })).toBeUndefined();
    expect(order.presentedAt(twin, TOUCH_DOWN)).toMatchObject({ role: 'scrollable', rect: rect(31, 456, 340, 355) });
  });

  it('the scene asks it at a point (`Scene.presentedAt`): under the Fees half sheet the surface at the touch-down presses its own rect and names no layer; asked for no target, a screen presented by shape alone is no stop — none', () => {
    const tree = screen('swiftFeesSheet');
    const field = find(tree, (n) => n.identifier === 'swift_payment.form.payee_city_input');
    const scene = sceneOf(tree);
    const atTouchDown = scene.presentedAt(TOUCH_DOWN, field);
    expect(atTouchDown).toMatchObject({ surface: { role: 'scrollable', rect: rect(31, 456, 340, 355) }, reach: rect(31, 456, 340, 355) });
    expect(atTouchDown?.layer).toBeUndefined();
    expect(scene.presentedAt({ x: 201, y: 175 }, field)).toMatchObject({ surface: { label: 'dismiss popup' }, reach: rect(-402, -874, 1206, 2622) });
    expect(scene.presentedAt(TOUCH_DOWN)).toBeUndefined();
  });

  it('none with no screen presented (Finportal\'s login), and none for a node not in this tree', () => {
    const login = screen('finportalLogin');
    const order = drawOrder(login);
    expect(order.presentedAt(find(login, (n) => n.identifier === 'lang_sk'), TOUCH_DOWN)).toBeUndefined();
    expect(order.presentedAt(uiNode({ role: 'button', label: 'elsewhere', rect: rect(0, 1000, 402, 50) }), TOUCH_DOWN)).toBeUndefined();
  });

  it('only a surface that draws over the node as a target counts — Finportal\'s Android login (its measured shape): the RN root\'s full-screen background leaf, then a later layer holding the `login_screen` scroll view over the whole screen. That scroll view is no cover of the background (the `target` column excuses it), so it is no presented surface over it either', () => {
    const PIXEL = rect(0, 0, 1080, 2220);
    const full = (children: UiNode[], more: Partial<UiNode> = {}) => uiNode({ role: 'container', rect: PIXEL, children, ...more });
    const background = uiNode({ role: 'other', rect: PIXEL });
    const card = uiNode({ role: 'container', identifier: 'login_card', rect: rect(44, 476, 992, 1100), children: [uiNode({ role: 'text', label: 'Login', identifier: 'login_title', rect: rect(99, 696, 882, 66) })] });
    const loginScreen = uiNode({ role: 'scrollable', identifier: 'login_screen', rect: PIXEL, clipsDescendants: true, children: [full([card])] });
    const layers = full([full([background]), full([full([uiNode({ role: 'scrollable', rect: PIXEL, children: [full([full([loginScreen])])] })])])]);
    const tree = full([full([full([full([full([layers], { identifier: 'content' })], { identifier: 'action_bar_root' })])])], { paddedTouchTargets: true });
    const order = drawOrder(tree);
    const seen = order.exposure(background, PIXEL);
    expect(coverNodes(seen.covers)).not.toContain(loginScreen);
    expect(seen.covers.filter((c) => c.presented)).toEqual([]);
    expect(order.presentedAt(background, { x: 540, y: 1776 })).toBeUndefined();
    expect(order.presentedOver(background)).toBeUndefined();
  });
});

/**
 * `presentedOver(node)` — `presentedAt` less the point: the presented screen's surface over the node wherever the node
 * lies, which the standing's remedy asks when its frame named none (ui-tree/standing.ts#remedied). The same rule, so
 * the same rows: what draws for the node as a target (the `target` column) and is a presented screen's surface.
 */
describe('presentedOver — the presented screen\'s surface over a node, geometry-free (ADR 0018)', () => {
  const screen = (key: string) => STACKED.screens[key];
  const find = (tree: UiNode, keep: (n: UiNode) => boolean) => [...everyNode(tree)].find(keep)!;

  it('measured: a cell wholly below the fold beneath Contacts\' discard popover — the action sheet WDA types in the popover\'s layer, its one cover; a field wholly below beneath the Fees half sheet — the sheet\'s form, drawn last', () => {
    const popover = DISCARD_POPOVER_KEYBOARD_DOWN;
    expect(drawOrder(popover).presentedOver(find(popover, (n) => n.role === 'container' && n.label === 'add instant message'))).toMatchObject({ label: 'Are you sure you want to discard this new contact?', rect: rect(10, 78, 240, 169) });
    const fees = screen('swiftFeesSheet');
    expect(drawOrder(fees).presentedOver(find(fees, (n) => n.identifier === 'swift_payment.form.bank_country_select'))).toMatchObject({ role: 'scrollable', rect: rect(31, 456, 340, 355) });
  });

  it('only what draws for the node as a target: Finportal\'s Android login background, under a later layer holding the `login_screen` scroll view the `target` column excuses — none', () => {
    const PIXEL = rect(0, 0, 1080, 2220);
    const full = (children: UiNode[], more: Partial<UiNode> = {}) => uiNode({ role: 'container', rect: PIXEL, children, ...more });
    const background = uiNode({ role: 'other', rect: PIXEL });
    const card = uiNode({ role: 'container', identifier: 'login_card', rect: rect(44, 476, 992, 1100), children: [uiNode({ role: 'text', label: 'Login', identifier: 'login_title', rect: rect(99, 696, 882, 66) })] });
    const loginScreen = uiNode({ role: 'scrollable', identifier: 'login_screen', rect: PIXEL, clipsDescendants: true, children: [full([card])] });
    const layers = full([full([background]), full([full([uiNode({ role: 'scrollable', rect: PIXEL, children: [full([full([loginScreen])])] })])])]);
    const tree = full([full([full([full([full([layers], { identifier: 'content' })], { identifier: 'action_bar_root' })])])], { paddedTouchTargets: true });
    expect(drawOrder(tree).presentedOver(background)).toBeUndefined();
  });

  it('residual, the Fees half sheet\'s hidden twin `PopoverDismissRegion` in the SWIFT form\'s own layer: the real dim, of the same frame, is excused by the target column (`sameFrame`) and never named — the sheet\'s form is', () => {
    const tree = screen('swiftFeesSheet');
    const [twin, dim] = [...everyNode(tree)].filter((n) => n.label === 'dismiss popup');
    const over = drawOrder(tree).presentedOver(twin);
    expect(over).not.toBe(dim);
    expect(over).toMatchObject({ role: 'scrollable', rect: rect(31, 456, 340, 355) });
  });

  it('a hidden subtree (ADR 0019) is no presented screen: the SWIFT form pushed over the tab host, the host\'s hidden tab bar listed after the form — none over its rows; and none with no screen presented, nor for a node not in this tree', () => {
    const pushed = SWIFT_PUSHED;
    const row = find(pushed, (n) => n.identifier === 'swift_payment.form.payee_country_select');
    expect(drawOrder(pushed).presentedOver(row)).toBeUndefined();
    const login = screen('finportalLogin');
    expect(drawOrder(login).presentedOver(find(login, (n) => n.identifier === 'lang_sk'))).toBeUndefined();
    expect(drawOrder(login).presentedOver(uiNode({ role: 'button', label: 'elsewhere', rect: rect(0, 1000, 402, 50) }))).toBeUndefined();
  });
});

/**
 * A Compose `Button` reaches uiautomator as a wrapper holding its label text and, AFTER it, an unlabelled clickable
 * `button` of about the wrapper's rect; a list row's label node has the row's avatar text, one wrapper down, lying on it
 * (docs/bugs/2026-10-09-android-compose-button-text-refused-as-under-its-own-button.md — a regression of round 5's C3:
 * `tap text:"LOGIN"` refused, `scroll_until` calling it a layout defect, `fully: true` never stopping on a row).
 */
describe('exposure — a Compose label\'s own control, a row\'s own content (2026-10-09)', () => {
  const PIXEL = rect(0, 0, 1080, 2220);
  const parse = (xml: string) => {
    const tree = parseDump(xml);
    const find = (p: (n: UiNode) => boolean) => [...everyNode(tree)].find(p)!;
    return { tree, find, order: drawOrder(tree) };
  };
  /**
   * The round-5 ui_snapshots (tests/fixtures/android-ui-snapshot-compose.json), by screen — each root marked
   * `paddedTouchTargets`, as the parser marks every uiautomator root since the snapshots were taken (code review of round 6b, P2).
   */
  const snapshots = async (): Promise<Record<string, UiNode>> =>
    Object.fromEntries(
      Object.entries((JSON.parse(await readFile(new URL('../fixtures/android-ui-snapshot-compose.json', import.meta.url), 'utf8')) as { screens: Record<string, UiNode> }).screens).map(
        ([screen, tree]) => [screen, { ...tree, paddedTouchTargets: true as const }],
      ),
    );
  /** Every text in `tree` with a later `button` sibling holding it whole — the shape the bug note measured. */
  const labelled = (tree: UiNode): UiNode[] =>
    [...everyNode(tree)].flatMap((parent) =>
      parent.children.filter((n, i) => n.role === 'text' && parent.children.slice(i + 1).some((b) => b.role === 'button' && b.rect.x <= n.rect.x && b.rect.y <= n.rect.y && b.rect.x + b.rect.width >= n.rect.x + n.rect.width && b.rect.y + b.rect.height >= n.rect.y + n.rect.height)),
    );

  it('the round-5 ui_snapshots: every text under its own control — LOGIN, PAY / PAY ME / SCAN QR, Contacts\' "No thanks", Save, "Add phone" (cut to 96 px), "Add fields" (to 76), the rows cut at the tab bar — shows whole, its centre tapped', async () => {
    const seen: string[] = [];
    for (const [screen, tree] of Object.entries(await snapshots())) {
      const order = drawOrder(tree);
      for (const text of labelled(tree)) {
        const exposure = order.exposure(text, PIXEL);
        seen.push(`${screen} ${text.label}`);
        expect({ screen, label: text.label, covers: exposure.covers, moved: exposure.tapAt?.moved }).toEqual({ screen, label: text.label, covers: [], moved: false });
      }
    }
    expect(seen.length).toBe(91);
    for (const label of ['LOGIN', 'PAY', 'PAY ME', 'SCAN QR', 'No thanks', 'Sync device and SIM contacts', 'Save', 'Add phone', 'Add fields']) expect(seen.some((s) => s.endsWith(` ${label}`))).toBe(true);
  });

  it('…the measured shapes in them: the control spans its wrapper\'s width, inset only vertically by a share that varies; a row\'s button stays whole where the row\'s container is cut', async () => {
    const { contactsCreateStaged, contactsCreate, accountDetail } = await snapshots();
    const wrapperOf = (tree: UiNode, label: string) => [...everyNode(tree)].find((p) => p.children.some((c) => c.label === label))!;
    const shape = (tree: UiNode, label: string) => {
      const wrapper = wrapperOf(tree, label);
      return { wrapper: wrapper.rect, button: wrapper.children.find((c) => c.role === 'button' && c.rect.x === wrapper.rect.x)!.rect };
    };
    expect(shape(contactsCreateStaged, 'Add fields')).toEqual({ wrapper: rect(132, 2067, 312, 132), button: rect(132, 2078, 312, 76) });
    expect(shape(contactsCreate, 'Add phone')).toEqual({ wrapper: rect(105, 2047, 261, 132), button: rect(105, 2058, 261, 96) });
    const cut = [...everyNode(accountDetail)].filter((n) => n.identifier === 'transactions.list.row_29' || n.identifier === 'transactions.list.row_30');
    expect(cut.map((row) => [row.rect, row.children.at(-1)!.rect])).toEqual([
      [rect(66, 1784, 948, 56), rect(66, 1784, 948, 143)],
      [rect(66, 2088, 948, 99), rect(66, 2044, 948, 143)],
    ]);
    // The label nodes of the rows wholly in the list, clear of the tab bar: no cover — the avatar's text is their own.
    const order = drawOrder(accountDetail);
    const rows = [...everyNode(accountDetail)].filter((n) => n.role === 'other' && n.label?.startsWith('Loan repayment') && n.rect.y >= 401 && n.rect.y + n.rect.height <= 1840);
    expect(rows).toHaveLength(5);
    for (const row of rows) expect(coverNodes(order.exposure(row, PIXEL).covers)).toEqual([]);
  });

  it('the round-5 ui_snapshots\' ICON buttons — Contacts\' Cancel, More options, Delete: the label node under a control padded by 11 px on all four sides of its 132×132 wrapper shows whole, its centre tapped (a refusal at 2f98900)', async () => {
    const { contactsCreateStaged, contactsCreate } = await snapshots();
    const icons = (tree: UiNode) =>
      [...everyNode(tree)].flatMap((parent) =>
        parent.children.flatMap((n, i) => {
          const control = parent.children.slice(i + 1).find((b) => b.role === 'button' && !b.label && rectWithin(n.rect, b.rect) && b.rect.x !== parent.rect.x);
          return n.label && control ? [{ label: n.label, n, wrapper: parent.rect, control: control.rect }] : [];
        }),
      );
    const seen: string[] = [];
    for (const [screen, tree] of Object.entries({ contactsCreateStaged, contactsCreate })) {
      const order = drawOrder(tree);
      for (const { label, n, wrapper, control } of icons(tree)) {
        seen.push(`${screen} ${label}`);
        expect([wrapper.width, wrapper.height, control.x - wrapper.x, control.y - wrapper.y, control.width, control.height, n.rect.width, n.rect.height]).toEqual([132, 132, 11, 11, 110, 110, 66, 66]);
        expect(order.exposure(n, PIXEL)).toMatchObject({ covers: [], shows: 1, tapAt: { point: rectCentre(control), moved: false } });
      }
    }
    expect(seen.sort()).toEqual(['contactsCreate Cancel', 'contactsCreate Delete', 'contactsCreate More options', 'contactsCreate More options', 'contactsCreateStaged Cancel', 'contactsCreateStaged Delete', 'contactsCreateStaged More options']);
  });

  it.each([
    ['LOGIN', COMPOSE.login, rect(44, 1402, 992, 121), { x: 540, y: 1463 }],
    ['SIGN IN', COMPOSE.signIn, rect(44, 1808, 992, 121), { x: 541, y: 1869 }],
    ['DISCARD', COMPOSE.discard, rect(638, 1192, 276, 121), { x: 776, y: 1253 }],
    ['KEEP EDITING', COMPOSE.discard, rect(262, 1192, 376, 121), { x: 450, y: 1253 }],
    ['No thanks', COMPOSE.noThanks, rect(44, 1967, 992, 110), { x: 541, y: 2023 }],
  ])('through the parser — %s: the unlabelled clickable `button` after the text, spanning its wrapper\'s width and holding it, is its own control — no cover; its centre is tapped', (label, xml, button, centre) => {
    const { find, order } = parse(xml);
    const text = find((n) => n.label === label);
    expect(find((n) => n.role === 'button' && n.rect.x === button.x && n.rect.y === button.y)).toMatchObject({ label: null, rect: button });
    const seen = order.exposure(text, PIXEL);
    expect(seen).toMatchObject({ covers: [], shows: 1, tapAt: { point: centre, moved: false } });
    expect(seen.centreCover).toBeUndefined();
    expect(coverAtPoint(seen.covers, centre)?.node).toBeUndefined();
  });

  it('Account Detail through the parser: the avatar\'s text `LR`, in the avatar\'s wrapper and wholly inside the row\'s label node, is the row\'s own content — the label node shows whole; the floating tab bar\'s host still covers the row beneath it', () => {
    const { find, order } = parse(COMPOSE.accountDetail);
    const label = find((n) => n.label === 'Loan repayment, 17.12.2025, +493.00 EUR');
    expect(label).toMatchObject({ role: 'other', rect: rect(66, 951, 948, 143) });
    expect(order.exposure(label, PIXEL)).toMatchObject({ covers: [], shows: 1, tapAt: { point: { x: 540, y: 1023 }, moved: false } });
    const host = find((n) => n.role === 'container' && n.rect.y === 1840 && n.rect.x === 66);
    const lower = find((n) => n.label === 'Card payment, 15.12.2025, -12.00 EUR');
    const seen = order.exposure(lower, PIXEL);
    expect(seen.covers[0].node).toBe(host);
    expect(coverNodes(seen.covers)).not.toContain(find((n) => n.label === 'CP'));
    expect(seen.shows).toBeCloseTo(10 / 143);
  });

  it('WDA (wda-source-myport-login-keyboard.json): `login_support`, a childless RN view, has its sibling `login_support_email` drawn on it — and that sibling\'s text `podpora@finportal.sk` is its own content too, no cover (a cover at dd50327)', async () => {
    const tree = parseWdaSource(await readFile(new URL('../fixtures/wda-source-myport-login-keyboard.json', import.meta.url), 'utf8'));
    const nodes = [...everyNode(tree)];
    const support = nodes.find((n) => n.identifier === 'login_support')!;
    const email = nodes.find((n) => n.identifier === 'login_support_email')!;
    expect([support.children, email.children.map((c) => [c.role, c.label])]).toEqual([[], [['text', 'podpora@finportal.sk']]]);
    expect(coverNodes(drawOrder(tree).exposure(support, tree.rect).covers)).toEqual([]);
  });

  describe('what stays a cover', () => {
    const TEXT = rect(481, 1438, 118, 49);
    const text = () => uiNode({ role: 'text', label: 'LOGIN', rect: TEXT });
    const button = (r = rect(44, 1402, 992, 121), partial: Partial<UiNode> = {}) => uiNode({ role: 'button', rect: r, ...partial });
    const WRAPPER = rect(44, 1397, 992, 132);
    /** The label and `later` in `parent`'s rect, on a Compose screen (uiautomator's root mark, `paddedTouchTargets`). */
    const inParent = (target: UiNode, later: UiNode, parent = WRAPPER) =>
      uiNode({ role: 'container', rect: PIXEL, paddedTouchTargets: true, children: [uiNode({ role: 'container', rect: PIXEL, children: [uiNode({ role: 'container', rect: parent, children: [target, later] })] })] });
    const coversOf = (target: UiNode, later: UiNode, parent = WRAPPER) => coverNodes(drawOrder(inParent(target, later, parent)).exposure(target, PIXEL).covers);

    it('an interactive target is no label: a later button holding a button whole in their wrapper covers it', () => {
      const target = uiNode({ role: 'button', label: 'Inner', rect: TEXT });
      const later = button();
      expect(coversOf(target, later)).toEqual([later]);
    });

    it('a scrim or backdrop: a clickable sibling in a SCREEN-SIZED parent (an RN transparent Modal\'s Pressable), or screen-sized itself in a full-width sheet (a dismiss region), covers the text it holds', () => {
      const target = text();
      const scrim = button(PIXEL);
      expect(coversOf(target, scrim, PIXEL)).toEqual([scrim]);
      // Spanning a screen-sized layout's width, not screen-sized itself: the layout is no wrapper of it.
      const band = button(rect(0, 1300, 1080, 300));
      expect(coversOf(target, band, PIXEL)).toEqual([band]);
      // Screen-sized itself, spanning a sheet's width and reaching past it.
      const past = button(PIXEL);
      expect(coversOf(target, past, rect(0, 400, 1080, 1820))).toEqual([past]);
    });

    it('the control spans its wrapper\'s WIDTH, as measured: one inset by a pixel on either side or shifted by one, one spanning only the height, one not holding the label whole (a clear button), one that says something (a label, a value) covers it; one reaching past the wrapper vertically (a row cut at the list\'s edge) does not', () => {
      const target = text();
      for (const r of [rect(45, 1402, 991, 121), rect(44, 1402, 991, 121), rect(45, 1402, 992, 121), rect(400, 1397, 300, 132), rect(560, 1440, 60, 45)]) {
        const later = button(r);
        expect(coversOf(target, later)).toEqual([later]);
      }
      for (const said of [button(undefined, { label: 'LOG IN' }), button(undefined, { value: 'on' })]) expect(coversOf(target, said)).toEqual([said]);
      expect(coversOf(target, button(rect(44, 1300, 992, 300)))).toEqual([]);
      // Spanning the width but missing the label's bottom: a cover.
      const low = uiNode({ role: 'text', label: 'LOGIN', rect: rect(481, 1500, 118, 25) });
      const upper = button(rect(44, 1397, 992, 110));
      expect(coversOf(low, upper)).toEqual([upper]);
    });

    it('a control of ANOTHER parent covers: the pinned CONTINUE bar after the list, a bar in a sheet beside the label\'s wrapper, an unlabelled Surface spanning a wrapper of its own', () => {
      const target = text();
      const bar = button(rect(44, 1400, 992, 132));
      const tree = uiNode({ role: 'container', rect: PIXEL, children: [uiNode({ role: 'container', rect: rect(0, 0, 1080, 1500), clipsDescendants: true, children: [uiNode({ role: 'container', rect: WRAPPER, children: [target] })] }), bar] });
      expect(coverNodes(drawOrder(tree).exposure(target, PIXEL).covers)).toEqual([bar]);
      const sheet = uiNode({ role: 'container', rect: rect(0, 1200, 1080, 600), children: [uiNode({ role: 'container', rect: WRAPPER, children: [target] }), bar] });
      expect(coverNodes(drawOrder(uiNode({ role: 'container', rect: PIXEL, children: [sheet] })).exposure(target, PIXEL).covers)).toEqual([bar]);
      const surface = button(rect(44, 1392, 992, 136));
      const own = uiNode({ role: 'container', rect: rect(44, 1390, 992, 140), children: [surface] });
      const beside = uiNode({ role: 'container', rect: PIXEL, children: [uiNode({ role: 'container', rect: rect(0, 1200, 1080, 600), children: [uiNode({ role: 'container', rect: WRAPPER, children: [target] }), own] })] });
      expect(coverNodes(drawOrder(beside).exposure(target, PIXEL).covers)).toEqual([own, surface]);
    });

    it('a classic View\'s pinned CTA in the SAME layout as a text (review of fix/r6, synthetic): LOG IN over "Forgot password?" with the keyboard up, CONTINUE over the terms, a sheet\'s PAY over its fee — inset from the layout\'s sides and labelled: a cover', () => {
      const cases: [string, string, string][] = [
        ['Forgot password?', 'LOG IN', CLASSIC_VIEWS.loginImeUp],
        ['By continuing you accept the terms', 'CONTINUE', CLASSIC_VIEWS.terms],
        ['Fee: 2.00 EUR', 'PAY', CLASSIC_VIEWS.sheet],
      ];
      for (const [label, cta, xml] of cases) {
        const { find, order } = parse(xml);
        const seen = order.exposure(find((n) => n.label === label), PIXEL);
        expect(seen.covers.map(({ node: n }) => n.label)).toEqual([cta]);
        expect(seen.tapAt).toBeUndefined();
      }
      // Unlabelled, LOG IN still covers: it does not span its layout's width, nor is it padded evenly on all four sides (40, 40, 940, 20).
      const { find, order } = parse(CLASSIC_VIEWS.loginImeUp);
      const login = find((n) => n.label === 'LOG IN');
      login.label = null;
      expect(coverNodes(order.exposure(find((n) => n.label === 'Forgot password?'), PIXEL).covers)).toEqual([login]);
    });

    describe('the icon button\'s control, padded on all four sides (Contacts\' Cancel: wrapper 11,88 132x132, control 22,99 110x110, label node 44,121 66x66)', () => {
      const ICON_WRAPPER = rect(11, 88, 132, 132);
      const icon = (r = rect(44, 121, 66, 66)) => uiNode({ role: 'other', label: 'Cancel', rect: r });

      it('padded evenly, or within a pixel (a centred placement rounded — 126 px around 105 at 2.625 dp/px, insets 11 and 10): no cover', () => {
        expect(coversOf(icon(), button(rect(22, 99, 110, 110)), ICON_WRAPPER)).toEqual([]);
        expect(coversOf(icon(rect(43, 120, 63, 63)), button(rect(22, 99, 105, 105)), rect(11, 88, 126, 126))).toEqual([]);
        // A 24-dp control padded to 48 dp at 2.625 px/dp: 63 px in 126, insets 32 and 31 — 2×32 is the side plus the rounding's pixel.
        expect(coversOf(icon(rect(51, 128, 47, 47)), button(rect(43, 120, 63, 63)), rect(11, 88, 126, 126))).toEqual([]);
      });

      it('a cover: a control flush with a side (insets 0 and 1), insets differing by two, an inset over half the control\'s side, a label off the control\'s centre on either axis, a control that says something', () => {
        for (const r of [rect(11, 88, 131, 131), rect(22, 99, 108, 110)]) {
          const later = button(r);
          expect(coversOf(icon(), later, ICON_WRAPPER)).toEqual([later]);
        }
        const wide = button(rect(55, 132, 44, 44));
        expect(coversOf(icon(rect(66, 143, 22, 22)), wide, ICON_WRAPPER)).toEqual([wide]);
        // The SHORTER side bounds it: insets of 30 around a 110×40 control (2×30 over 40, under 110).
        const flat = button(rect(41, 118, 110, 40));
        expect(coversOf(icon(rect(86, 128, 20, 20)), flat, rect(11, 88, 170, 100))).toEqual([flat]);
        // Off by 2 px on either axis is off centre too (centre (77,154) → (79,154), (77,156)).
        for (const r of [rect(24, 101, 40, 40), rect(57, 101, 40, 40), rect(24, 134, 40, 40), rect(59, 134, 40, 40), rect(57, 136, 40, 40)]) {
          const later = button(rect(22, 99, 110, 110));
          expect(coversOf(icon(r), later, ICON_WRAPPER)).toEqual([later]);
        }
        const said = button(rect(22, 99, 110, 110), { label: 'Close' });
        expect(coversOf(icon(), said, ICON_WRAPPER)).toEqual([said]);
      });

      it('residual, stated: an icon button CUT by a list\'s or scroll view\'s edge — insets 11, 11, 11, 41 — is still refused', () => {
        const cut = button(rect(22, 99, 110, 80));
        expect(coversOf(icon(rect(44, 121, 66, 56)), cut, ICON_WRAPPER)).toEqual([cut]);
      });

      it('only where measured — uiautomator\'s tree (`paddedTouchTargets`; code review of round 6b, P2): under WDA an unlabelled button centred over a text with an even margin in its card stays a cover; spanning the card\'s width, it is the text\'s own control there too', () => {
        // The same shape on the iPhone 17 under WDA: a card `Other` → its text, then an unlabelled overlay `Button` 8 pt in.
        const label = uiNode({ role: 'text', label: 'Cancel', rect: rect(40, 220, 40, 20) });
        const overlay = button(rect(20, 200, 80, 60));
        const card = uiNode({ role: 'container', rect: rect(12, 192, 96, 76), children: [label, overlay] });
        const wda = uiNode({ role: 'container', rect: rect(0, 0, 402, 874), children: [uiNode({ role: 'container', rect: rect(0, 0, 402, 874), children: [card] })] });
        expect(coverNodes(drawOrder(wda).exposure(label, rect(0, 0, 402, 874)).covers)).toEqual([overlay]);
        // The mark alone makes it the label's own: the shape is the measured one.
        expect(coverNodes(drawOrder({ ...wda, paddedTouchTargets: true }).exposure(label, rect(0, 0, 402, 874)).covers)).toEqual([]);
        // spansWidth is not gated: a text button's control (the card's x and width) is the text's own on any tree.
        const wide = button(rect(12, 200, 96, 60));
        const spanning = uiNode({ role: 'container', rect: rect(0, 0, 402, 874), children: [uiNode({ role: 'container', rect: rect(12, 192, 96, 76), children: [label, wide] })] });
        expect(coverNodes(drawOrder(spanning).exposure(label, rect(0, 0, 402, 874)).covers)).toEqual([]);
      });

      it('through the WDA parser: no tree it gives carries the mark', async () => {
        const tree = parseWdaSource(await readFile(new URL('../fixtures/wda-source-myport-login-keyboard.json', import.meta.url), 'utf8'));
        expect([...everyNode(tree)].some((n) => n.paddedTouchTargets === true)).toBe(false);
        expect(parseDump(COMPOSE.login).paddedTouchTargets).toBe(true);
      });

      it('a centred dialog-like overlay in a screen-sized parent, padded evenly, still covers', () => {
        const target = uiNode({ role: 'text', label: 'Are you sure?', rect: rect(440, 1060, 200, 100) });
        const overlay = button(rect(40, 40, 1000, 2140));
        expect(coversOf(target, overlay, PIXEL)).toEqual([overlay]);
      });
    });

    it('a non-interactive node of the wrapper\'s width holding the label — an opaque card, a loading view — covers it', () => {
      const target = text();
      for (const role of ['image', 'progress', 'other']) {
        const card = uiNode({ role, rect: rect(44, 1402, 992, 121), ...(role === 'other' && { label: 'Loading' }) });
        expect(coversOf(target, card)).toEqual([card]);
      }
    });

    it('in idb\'s flat list every node is a sibling, of the 0×0 root that no control spans: a later button holding the text, its top at the text\'s, covers it', () => {
      const target = text();
      const later = button(rect(44, 1438, 992, 121));
      expect(coverNodes(drawOrder(uiNode({ role: 'container', rect: rect(0, 0, 0, 0), flatList: true, children: [uiNode({ role: 'other', rect: PIXEL }), target, later] })).exposure(target, PIXEL).covers)).toEqual([later]);
      // Nor an icon's padded control: no node lies inside the 0×0 root (both below the top bar's band, so content).
      const icon = uiNode({ role: 'other', label: 'Cancel', rect: rect(44, 1121, 66, 66) });
      const padded = button(rect(22, 1099, 110, 110));
      expect(coverNodes(drawOrder(uiNode({ role: 'container', rect: rect(0, 0, 0, 0), flatList: true, children: [uiNode({ role: 'other', rect: PIXEL }), icon, padded] })).exposure(icon, PIXEL).covers)).toEqual([padded]);
    });

    it('a row\'s own content is narrow: in the avatar\'s wrapper, an interactive node, a text reaching outside the label node, and any text under a full-width sibling (a header) cover it; so does content two wrappers down', () => {
      const label = uiNode({ role: 'other', label: 'Loan repayment', rect: rect(66, 951, 948, 143) });
      const rowOf = (sibling: UiNode) => uiNode({ role: 'container', rect: PIXEL, children: [uiNode({ role: 'container', rect: rect(66, 951, 948, 143), children: [label, sibling] })] });
      const avatar = (inner: UiNode) => uiNode({ role: 'container', rect: rect(116, 979, 88, 88), children: [inner] });
      const own = uiNode({ role: 'text', label: 'LR', rect: rect(136, 999, 48, 49) });
      expect(coverNodes(drawOrder(rowOf(avatar(own))).exposure(label, PIXEL).covers)).toEqual([]);
      const badge = uiNode({ role: 'button', label: 'Edit', rect: rect(136, 999, 48, 49) });
      expect(coverNodes(drawOrder(rowOf(avatar(badge))).exposure(label, PIXEL).covers)).toEqual([badge]);
      const out = uiNode({ role: 'text', label: 'LR', rect: rect(136, 1080, 48, 49) });
      expect(coverNodes(drawOrder(rowOf(avatar(out))).exposure(label, PIXEL).covers)).toEqual([out]);
      const header = uiNode({ role: 'container', label: 'December', rect: rect(66, 940, 948, 60), children: [uiNode({ role: 'text', label: 'December', rect: rect(100, 951, 300, 40) })] });
      expect(coverNodes(drawOrder(rowOf(header)).exposure(label, PIXEL).covers)).toEqual([header, header.children[0]]);
      const deep = uiNode({ role: 'text', label: 'LR', rect: rect(136, 999, 48, 49) });
      expect(coverNodes(drawOrder(rowOf(avatar(uiNode({ role: 'container', rect: rect(126, 990, 68, 68), children: [deep] })))).exposure(label, PIXEL).covers)).toEqual([deep]);
    });

    it('…and only of a CHILDLESS target: the list holding the rows, with the tab bar\'s host drawn on it as its sibling, still has the tab and its label over it', () => {
      const tree = parseDump(COMPOSE.accountDetail);
      const list = [...everyNode(tree)].find((n) => n.clipsDescendants === true)!;
      const covers = coverNodes(drawOrder(tree).exposure(list, PIXEL).covers);
      expect(covers.map((n) => n.identifier ?? n.label)).toEqual(['nav.tab_home', 'Home']);
    });
  });
});

describe('exposure.centreExcused — the later nodes the target column excused that hold the centre (the dismissal picker\'s one read, docs/adr/0016-the-dismissal-picker-asks-the-tap-standing.md)', () => {
  const IPHONE = rect(0, 0, 402, 874);

  it('counted at the node\'s reach, as cover.ts#coverAtPoint asks: a keyboard-owned key pinned at the bottom of idb\'s flat list holds a text below its frame — excused, no cover, yet there', () => {
    const app = uiNode({ role: 'other', label: 'app', rect: IPHONE });
    const under = uiNode({ role: 'text', label: 'Under', rect: rect(42, 840, 150, 20) }); // centre (117,850), below the key's frame (780–824)
    const key = uiNode({ role: 'button', label: 'Done', ofKeyboard: true, rect: rect(24, 780, 354, 44) });
    const seen = drawOrder(uiNode({ role: 'container', rect: rect(0, 0, 0, 0), flatList: true, children: [app, under, key] })).exposure(under, IPHONE);
    expect(seen).toMatchObject({ covers: [], centreExcused: [key], tapAt: { moved: false } });
  });

  it('only the excused that hold the centre — a cover there is a cover, not excused — and none when the centre lies outside `within`', () => {
    const title = uiNode({ role: 'text', label: 'Title', rect: rect(100, 700, 200, 100) }); // centre (200,750)
    const twin = uiNode({ role: 'button', label: 'Twin', rect: rect(100, 700, 200, 100) }); // the `sameFrame` row
    const aside = uiNode({ role: 'button', label: 'Key', ofKeyboard: true, rect: rect(100, 700, 50, 30) }); // excused, off the centre
    const bar = uiNode({ role: 'button', label: 'Bar', rect: rect(0, 745, 402, 10) }); // a cover across the centre
    const order = drawOrder(uiNode({ role: 'container', rect: IPHONE, children: [title, twin, aside, bar] }));
    expect(order.exposure(title, IPHONE)).toMatchObject({ covers: [{ node: bar }], centreCover: { node: bar }, centreExcused: [twin] });
    // The box ends at 740, above the centre: the twin still meets what shows, but no tap lands at the centre.
    expect(order.exposure(title, rect(0, 0, 402, 740))).toMatchObject({ covers: [], centreExcused: [] });
  });
});

describe('exposure — a React Native field\'s floating label is its own field\'s (the RN lab app, rn-field\'s N and M)', () => {
  // Round 7's RN lab app.
  /** The RN lab app's rn-field under WDA (iPhone 17, iOS 27): each input inside an unnamed wrapper of its rect. Parsed afresh per case: the negatives edit it. */
  const wda = async () => parseWdaSource(await readFile(new URL('../fixtures/wda-source-rn-field.json', import.meta.url), 'utf8'));
  /** The same screen under uiautomator (averi_lab, API 33, 1080x2220 at 2.75): the label 3 px past its EditText above and below. */
  const xml = async () => parseDump(await readFile(new URL('../fixtures/uiautomator-rn-field.xml', import.meta.url), 'utf8'));
  const byId = (tree: UiNode, id: string) => [...everyNode(tree)].find((n) => n.identifier === id)!;
  const exposed = (tree: UiNode) => drawOrder(tree).exposure(byId(tree, 'lab.rn-field.N'), tree.rect);
  /** N's field and the unnamed wrapper WDA lists it in, as captured. */
  const wrapped = (tree: UiNode) => {
    const field = byId(tree, 'lab.rn-field.N.field');
    const wrapper = [...everyNode(tree)].find((n) => n.children.length === 1 && n.children[0] === field)!;
    return { field, wrapper };
  };

  it('WDA (docs/bugs/2026-10-19-lab-ios-wda-rn-text-input-wrapped-in-its-component-view-reads-as-a-cover-of-its-own-label.md): the input inside its unnamed wrapper of its own rect is the label\'s field — nothing over `Payee’s name`, tapped at its centre', async () => {
    const tree = await wda();
    const { field, wrapper } = wrapped(tree);
    expect(wrapper).toMatchObject({ role: 'container', label: null, identifier: null, rect: field.rect });
    expect(exposed(tree)).toMatchObject({ covers: [], shows: 1, tapAt: { point: { x: 116, y: 143 }, moved: false } });
    expect(exposed(tree).centreExcused).toEqual(expect.arrayContaining([wrapper, field]));
    // M, the multiline field: its text view's `Horizontal scroll bar` (69,499 264x10) over the label's centre too — no cover.
    const m = byId(tree, 'lab.rn-field.M');
    expect(drawOrder(tree).exposure(m, tree.rect)).toMatchObject({ covers: [], shows: 1, tapAt: { moved: false } });
  });

  it('…and the wrapper stays a node of its own when it is anything more: named, interactive, of another rect, or holding anything else — the field in it covers', async () => {
    const edits: ((w: UiNode) => void)[] = [
      (w) => (w.identifier = 'payee.card'),
      (w) => (w.label = 'Payee'),
      (w) => (w.role = 'button'),
      (w) => (w.rect = { ...w.rect, height: w.rect.height + 4 }),
      (w) => w.children.push(uiNode({ role: 'image', rect: rect(310, 134, 16, 16) })),
    ];
    for (const edit of edits) {
      const tree = await wda();
      const { field, wrapper } = wrapped(tree);
      edit(wrapper);
      expect(coverNodes(exposed(tree).covers)).toContain(field);
    }
  });

  it('…and an unrelated container over the label still covers: one holding a text laid after it over the label', async () => {
    const tree = await wda();
    const { wrapper } = wrapped(tree);
    const banner = uiNode({ role: 'container', rect: rect(69, 128, 264, 30), children: [uiNode({ role: 'text', label: 'Offline', rect: rect(69, 128, 264, 30) })] });
    const parent = [...everyNode(tree)].find((n) => n.children.includes(wrapper))!;
    parent.children.splice(parent.children.indexOf(wrapper) + 1, 0, banner);
    expect(coverNodes(exposed(tree).covers)).toContain(banner);
  });

  it('…and a text a field merely lies over, in a screen-sized parent, still covers — the label must span the field\'s height: a chat composer over a message, a search field over a header title, the composer in an unnamed wrapper of its rect, an editor of 0.8 of the screen over "Draft saved", a label at the top of a tall multiline field', () => {
    const screen = (...children: UiNode[]) => uiNode({ role: 'container', rect: IPHONE_BOX, children: [uiNode({ role: 'container', rect: IPHONE_BOX, children })] });
    const field = (r: ReturnType<typeof rect>) => uiNode({ role: 'textfield', rect: r });
    const cases: [UiNode, UiNode, UiNode][] = [];
    const message = uiNode({ role: 'text', label: 'See you at 6', rect: rect(16, 800, 140, 20) });
    const composer = field(rect(0, 790, 402, 44));
    cases.push([message, composer, composer]);
    const title = uiNode({ role: 'text', label: 'Payments', rect: rect(16, 104, 90, 22) });
    const search = field(rect(8, 100, 386, 36));
    cases.push([title, search, search]);
    const message2 = uiNode({ role: 'text', label: 'See you at 6', rect: rect(16, 800, 140, 20) });
    const inner = field(rect(0, 790, 402, 44));
    cases.push([message2, uiNode({ role: 'container', rect: rect(0, 790, 402, 44), children: [inner] }), inner]);
    const saved = uiNode({ role: 'text', label: 'Draft saved', rect: rect(16, 400, 100, 20) });
    const editor = field(rect(0, 87, 402, 700));
    cases.push([saved, editor, editor]);
    // A label at the top of a tall multiline field, its top at the field's: the residual, a cover (unmeasured).
    const hint = uiNode({ role: 'text', label: 'Message', rect: rect(16, 501, 140, 20) });
    const multiline = field(rect(0, 500, 402, 120));
    cases.push([hint, multiline, multiline]);
    for (const [text, later, cover] of cases) expect(coverNodes(drawOrder(screen(text, later)).exposure(text, IPHONE_BOX).covers)).toContain(cover);
  });

  it('…and a text input filling the screen covers a label spanning its height', () => {
    const label = uiNode({ role: 'text', label: 'Write here', rect: rect(0, 1, 402, 872) });
    const input = uiNode({ role: 'textfield', rect: IPHONE_BOX });
    const tree = uiNode({ role: 'container', rect: IPHONE_BOX, children: [uiNode({ role: 'container', rect: rect(0, 0, 402, 874), children: [label, input] })] });
    expect(coverNodes(drawOrder(tree).exposure(label, IPHONE_BOX).covers)).toContain(input);
  });

  it('Android (docs/bugs/2026-10-19-lab-android-rn-label-overhanging-its-edittext-by-3-px-reads-as-covered-by-it.md): the label 3 px — 1 dp — past its EditText above and below is the field\'s: nothing over it, tapped at its centre', async () => {
    const tree = await xml();
    expect(byId(tree, 'lab.rn-field.N').rect).toEqual(rect(177, 360, 255, 61));
    expect(byId(tree, 'lab.rn-field.N.field').rect).toEqual(rect(177, 363, 726, 55));
    expect(exposed(tree)).toMatchObject({ covers: [], shows: 1, tapAt: { point: { x: 305, y: 391 }, moved: false } });
  });

  it('…up to the allowance on this screen, 5 px; 6 px past the field, or a valued field, covers', async () => {
    const grown = async (by: number) => {
      const tree = await xml();
      const label = byId(tree, 'lab.rn-field.N');
      label.rect = { ...label.rect, y: 363 - by, height: 55 + 2 * by };
      return tree;
    };
    expect(coverNodes(exposed(await grown(5)).covers)).toEqual([]);
    const past = await grown(6);
    expect(coverNodes(exposed(past).covers)).toEqual([byId(past, 'lab.rn-field.N.field')]);
    const valued = await xml();
    byId(valued, 'lab.rn-field.N.field').value = 'ACME s.r.o.';
    expect(coverNodes(exposed(valued).covers)).toEqual([byId(valued, 'lab.rn-field.N.field')]);
  });
});

describe('labelOverhang: how far a label may overhang its own field — 2 pt or dp, as a share of the screen', () => {
  it('half a percent of the screen\'s shorter side, rounded — 2 pt on the 402-pt iPhone 17 and a 320-pt one, 5 px on the 1080-px averi_lab (2.75), 7 px at 1440 (3.5), 4 px at 720 (2), either orientation', () => {
    expect(labelOverhang({ width: 402, height: 874 })).toBe(2);
    expect(labelOverhang({ width: 320, height: 568 })).toBe(2);
    expect(labelOverhang({ width: 1080, height: 2220 })).toBe(5);
    expect(labelOverhang({ width: 2220, height: 1080 })).toBe(5);
    expect(labelOverhang({ width: 1440, height: 3120 })).toBe(7);
    expect(labelOverhang({ width: 720, height: 1280 })).toBe(4);
  });
});

describe('minTapPiece: the least piece a tap may be aimed at, one formula for averi and the harness', () => {
  it('6 % of the screen\'s shorter side, rounded — 24 pt on the 402-pt iPhone 17, 65 px on the 1080-px Pixel 3a, either orientation', () => {
    expect(minTapPiece({ width: 402, height: 874 })).toBe(24);
    expect(minTapPiece({ width: 1080, height: 2220 })).toBe(65);
    expect(minTapPiece({ width: 2220, height: 1080 })).toBe(65);
  });
  it('is what the draw order\'s exposure answers as its minPiece', () => {
    const target = uiNode({ role: 'button', identifier: 't', rect: rect(0, 0, 100, 100) });
    expect(drawOrder(uiNode({ role: 'container', rect: rect(0, 0, 1080, 2220), children: [target] })).exposure(target, rect(0, 0, 1080, 2220)).minPiece).toBe(65);
  });
});
